// Public rate-confirmation signing client. Talks to the rateConSignApi Lambda Function URL.
// URL priority: VITE_RATE_CON_SIGN_API_URL env var → amplify_outputs.json custom.rateConSignUrl.
import outputs from '../../amplify_outputs.json'
import type { RateConRequiredField, RateConStatus } from '@/types/tms'

const envUrl: string | undefined =
  typeof import.meta.env.VITE_RATE_CON_SIGN_API_URL === 'string'
    ? import.meta.env.VITE_RATE_CON_SIGN_API_URL
    : undefined

// amplify_outputs.json is generated by the Amplify build pipeline; we expect the optional
// custom.rateConSignUrl value when the backend defines it.
const rawOutputs = outputs as { custom?: { rateConSignUrl?: unknown } | undefined }
const customUrl: string | undefined =
  typeof rawOutputs.custom?.rateConSignUrl === 'string' ? rawOutputs.custom.rateConSignUrl : undefined

export const RATE_CON_SIGN_API_URL = envUrl ?? customUrl ?? ''
export const rateConSignAvailable = !!RATE_CON_SIGN_API_URL

export class RateConSignError extends Error {
  status: number
  /** `REPLACED` = a newer version was sent; `INVALID` = the server refused the values (see `fieldErrors`). */
  code?: string
  fieldErrors?: Record<string, string>
  constructor(status: number, message: string, code?: string, fieldErrors?: Record<string, string>) {
    super(message)
    this.status = status
    this.code = code
    this.fieldErrors = fieldErrors
  }
}

/** What the signing page renders. The carrier never sees customer money — only their own. */
export interface RateConSignState {
  loadNumber: string
  carrierName: string
  brokerName: string
  status: RateConStatus
  expiresAt: string | null
  /** Still-empty fields only: a field the rep already entered is not asked for again. */
  requiredFields: RateConRequiredField[]
  /** Step AM: what the rep already entered, to prefill the form (never contains a required, still-empty field). */
  driverInfo?: { driverName?: string | null; driverPhone?: string | null; truckNumber?: string | null; trailerNumber?: string | null }
  totalCents: number
  /** Empty once signed: there is nothing left to read or sign. */
  pdfUrl: string
  version?: number
  /** Present when status is SIGNED. */
  signedAt?: string | null
  signerName?: string | null
}

function extractMessage(data: unknown, fallback: string): string {
  if (data && typeof data === 'object' && 'error' in data && typeof data.error === 'string') {
    return data.error
  }
  return fallback
}

function extractFieldErrors(data: unknown): Record<string, string> | undefined {
  if (data && typeof data === 'object' && 'fieldErrors' in data && data.fieldErrors && typeof data.fieldErrors === 'object') {
    return data.fieldErrors as Record<string, string>
  }
  return undefined
}

// The token rides at the top level of the body, beside the action: the endpoint has no
// auth of its own, so the token IS the credential and every call carries it.
async function post<T>(action: string, token: string, payload?: unknown): Promise<T> {
  if (!RATE_CON_SIGN_API_URL) {
    throw new RateConSignError(0, 'Rate confirmation signing endpoint is not configured')
  }
  const res = await fetch(RATE_CON_SIGN_API_URL, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ token, action, payload }),
  })
  const data = await res.json().catch(() => ({}))
  if (!res.ok) {
    const code = data && typeof data === 'object' && 'code' in data && typeof data.code === 'string' ? data.code : undefined
    throw new RateConSignError(res.status, extractMessage(data, res.statusText), code, extractFieldErrors(data))
  }
  return data as T
}

/** First successful call on a SENT rate con flips it to OPENED server-side. */
export async function getRateCon(token: string): Promise<RateConSignState> {
  return post('get', token)
}

/** The server stamps the PDF itself; the browser sends only the typed name, the agreement and the field values. */
export async function submitRateCon(input: {
  token: string
  signerName: string
  agreed: boolean
  fields: Record<string, string>
}): Promise<{ ok: true; alreadySigned: boolean; signedAt: string | null; signerName: string | null; version: number }> {
  const { token, ...payload } = input
  return post('submit', token, payload)
}

export async function declineRateCon(input: { token: string; reason: string }): Promise<{ ok: true }> {
  return post('decline', input.token, { reason: input.reason })
}
